import pandas as pd
import numpy as np


def run(inputs):
    target_state = inputs["target_state"]
    cdc_events = inputs["cdc_events"]

    # Build current state dict from target_state
    current_state = {}
    for row in target_state.itertuples(index=False):
        current_state[int(row.order_id)] = {
            "status": row.status,
            "amount": row.amount,
            "last_seq": int(row.last_seq),
        }

    # Deduplicate events by seq (at-least-once delivery -> apply once)
    dedup = cdc_events.drop_duplicates(subset="seq", keep="first")

    # Sort events by order_id then seq for deterministic per-order processing
    dedup = dedup.sort_values(["order_id", "seq"], kind="mergesort")

    tombstones_rows = []

    for order_id, grp in dedup.groupby("order_id", sort=False):
        order_id = int(order_id)
        existing = current_state.get(order_id)
        ever_had_row = existing is not None

        guard_seq = existing["last_seq"] if existing is not None else None

        grp_sorted = grp.sort_values("seq", kind="mergesort")

        filtered = []
        for ev in grp_sorted.itertuples(index=False):
            seq = int(ev.seq)
            if guard_seq is not None and seq <= guard_seq:
                continue
            filtered.append(ev)

        if not filtered:
            continue

        last_op = None
        last_seq_applied = None

        for ev in filtered:
            seq = int(ev.seq)
            op = ev.op
            status = ev.status
            amount = ev.amount

            if op in ("I", "U"):
                if existing is not None:
                    if op == "U" and pd.isna(amount):
                        new_amount = existing["amount"]
                    else:
                        new_amount = amount
                    existing = {
                        "status": status,
                        "amount": new_amount,
                        "last_seq": seq,
                    }
                else:
                    existing = {
                        "status": status,
                        "amount": amount,
                        "last_seq": seq,
                    }
                current_state[order_id] = existing
                ever_had_row = True
            elif op == "D":
                if existing is not None:
                    existing = None
                    current_state.pop(order_id, None)
                # if no existing row, D does nothing
            else:
                # unknown op, ignore defensively
                pass

            last_op = op
            last_seq_applied = seq

        if last_op == "D" and ever_had_row:
            tombstones_rows.append(
                {"order_id": order_id, "deleted_seq": last_seq_applied}
            )

    # Build new_state DataFrame
    if current_state:
        new_state_rows = []
        for oid, st in current_state.items():
            new_state_rows.append(
                {
                    "order_id": oid,
                    "status": st["status"],
                    "amount": st["amount"],
                    "last_seq": st["last_seq"],
                }
            )
        new_state = pd.DataFrame(
            new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
        )
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")
        new_state["amount"] = new_state["amount"].astype("float64")
        new_state["status"] = new_state["status"].astype(object)
    else:
        new_state = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "status": pd.Series(dtype="object"),
                "amount": pd.Series(dtype="float64"),
                "last_seq": pd.Series(dtype="int64"),
            }
        )

    if tombstones_rows:
        tombstones = pd.DataFrame(
            tombstones_rows, columns=["order_id", "deleted_seq"]
        )
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")
    else:
        tombstones = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "deleted_seq": pd.Series(dtype="int64"),
            }
        )

    return {"new_state": new_state, "tombstones": tombstones}
